import * as THREE from 'three/webgpu';
import { texture, uv, vec4, uniform, mix, color } from 'three/tsl';

export default function createNode(config, ctx) {
  const width = 1.6;
  const aspect = 320 / 512;
  const height = width * aspect;

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const imageUrl = config.assets?.imageUrl || '/prism-assets/chrome/ceramic-grain.map.png';
  const tex = ctx.textureLoader(imageUrl);
  if (tex) {
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.wrapS = THREE.ClampToEdgeWrapping;
    tex.wrapT = THREE.ClampToEdgeWrapping;
  }

  // Atlas region UV mapping (atlas 0, rect 0,0,512,320 -> full texture assumed atlas-sized)
  const atlasWidth = 512;
  const atlasHeight = 320;
  const rect = { x: 0, y: 0, w: 512, h: 320 };

  const uOffset = rect.x / atlasWidth;
  const vOffset = 1.0 - (rect.y + rect.h) / atlasHeight;
  const uScale = rect.w / atlasWidth;
  const vScale = rect.h / atlasHeight;

  const uvOffset = uniform(new THREE.Vector2(uOffset, vOffset));
  const uvScale = uniform(new THREE.Vector2(uScale, vScale));

  const mappedUv = uv().mul(uvScale).add(uvOffset);
  const baseColor = tex ? texture(tex, mappedUv) : vec4(color(config.visual?.colors?.surface || '#0b0b10'), 1.0);

  // subtle engineered gradient tint overlay for grain surface
  const inkColor = color(config.visual?.colors?.ink || '#16161d');
  const paperColor = color(config.visual?.colors?.paper || '#e8ecf2');
  const gradientMix = mix(inkColor, paperColor, uv().y).mul(0.06);

  material.colorNode = vec4(baseColor.rgb.add(gradientMix), baseColor.a);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'hub-journal-card-1';

  const pos = config.position || [0, -0.3, 0];
  const rot = config.rotation || [0, 0, 0];
  const scl = config.scale || [1, 1, 1];
  mesh.position.set(pos[0], pos[1], pos[2]);
  mesh.rotation.set(rot[0], rot[1], rot[2]);
  mesh.scale.set(scl[0], scl[1], scl[2]);

  // billboard behavior toward camera, updated externally via userData.update if scene loop calls it
  mesh.userData.billboard = true;
  mesh.userData.update = () => {
    if (ctx.camera) {
      mesh.quaternion.copy(ctx.camera.quaternion);
    }
  };

  const primitiveList = config.cinematicPrimitives || [];
  for (const primitive of primitiveList) {
    if (ctx.primitives[primitive.name]) {
      ctx.primitives[primitive.name](mesh, primitive.params);
    }
  }

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (tex && tex.dispose) tex.dispose();
  };

  return mesh;
}
